import "server-only";

import { env } from "cloudflare:workers";

/**
 * Local-only synthetic media for `npm run sample:gallery`.
 *
 * The seed script stores reserved `sample:` object keys in the local D1 photos
 * table. Real Google Drive file IDs can never contain a colon, so the prefix is
 * unforgeable through the normal upload flow. When a photo row carries one of
 * these keys, `driveMediaResponse` serves generated bytes from this module
 * instead of proxying Google Drive — but only when BOTH gates hold:
 *
 *   1. SAMPLE_MEDIA is set to "1"/"true" (a local .dev.vars entry; the deployed
 *      Worker never sets it), and
 *   2. the request targets a loopback hostname.
 *
 * Production requests therefore always take the Google Drive path and seeded
 * sample keys answer 404 outside local development.
 */
export const SAMPLE_OBJECT_PREFIX = "sample:";

const LOCAL_HOSTNAMES = new Set(["localhost", "127.0.0.1", "::1", "[::1]"]);

export function localSampleMediaEnabled(request: Request) {
  if (env.SAMPLE_MEDIA !== "1" && env.SAMPLE_MEDIA !== "true") return false;
  try {
    return LOCAL_HOSTNAMES.has(new URL(request.url).hostname);
  } catch {
    return false;
  }
}

/* ------------------------------------------------------------------ */
/* Generated PNG photos                                                */
/* ------------------------------------------------------------------ */

const PNG_SIGNATURE = Uint8Array.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
const IMAGE_WIDTH = 640;
const IMAGE_HEIGHT = 480;

let crcTable: Uint32Array | null = null;

function crc32(bytes: Uint8Array) {
  if (!crcTable) {
    crcTable = new Uint32Array(256);
    for (let n = 0; n < 256; n += 1) {
      let c = n;
      for (let k = 0; k < 8; k += 1) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      crcTable[n] = c >>> 0;
    }
  }
  let crc = 0xffffffff;
  for (const byte of bytes) crc = crcTable[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

function pngChunk(type: string, data: Uint8Array) {
  const chunk = new Uint8Array(12 + data.length);
  const view = new DataView(chunk.buffer);
  view.setUint32(0, data.length);
  for (let index = 0; index < 4; index += 1) chunk[4 + index] = type.charCodeAt(index);
  chunk.set(data, 8);
  view.setUint32(8 + data.length, crc32(chunk.subarray(4, 8 + data.length)));
  return chunk;
}

// Light→dark pairs give every seeded photo a distinct look in the grid.
const GRADIENTS: ReadonlyArray<readonly [readonly [number, number, number], readonly [number, number, number]]> = [
  [[244, 114, 182], [76, 29, 149]],
  [[251, 191, 36], [154, 52, 18]],
  [[52, 211, 153], [6, 78, 59]],
  [[96, 165, 250], [30, 58, 138]],
  [[249, 115, 22], [67, 20, 7]],
  [[167, 139, 250], [46, 16, 101]],
  [[45, 212, 191], [19, 78, 74]],
  [[253, 164, 175], [136, 19, 55]],
];

async function deflate(bytes: Uint8Array) {
  const stream = new Blob([bytes]).stream().pipeThrough(new CompressionStream("deflate"));
  return new Uint8Array(await new Response(stream).arrayBuffer());
}

async function samplePng(index: number) {
  const [from, to] = GRADIENTS[Math.abs(index) % GRADIENTS.length];
  const stride = IMAGE_WIDTH * 3 + 1;
  const pixels = new Uint8Array(stride * IMAGE_HEIGHT);
  for (let y = 0; y < IMAGE_HEIGHT; y += 1) {
    const row = y * stride; // Filter byte stays 0 (None).
    const depth = y / (IMAGE_HEIGHT - 1);
    for (let x = 0; x < IMAGE_WIDTH; x += 1) {
      const offset = row + 1 + x * 3;
      // A gentle horizontal shimmer keeps flat gradients visually distinct.
      const wobble = 0.05 * Math.sin((x / IMAGE_WIDTH) * Math.PI * 2);
      const mix = Math.min(1, Math.max(0, depth + wobble));
      pixels[offset] = Math.round(from[0] + (to[0] - from[0]) * mix);
      pixels[offset + 1] = Math.round(from[1] + (to[1] - from[1]) * mix);
      pixels[offset + 2] = Math.round(from[2] + (to[2] - from[2]) * mix);
    }
  }
  const header = new Uint8Array(13);
  const view = new DataView(header.buffer);
  view.setUint32(0, IMAGE_WIDTH);
  view.setUint32(4, IMAGE_HEIGHT);
  header[8] = 8; // Bit depth.
  header[9] = 2; // Truecolour RGB.
  const parts = [
    PNG_SIGNATURE,
    pngChunk("IHDR", header),
    pngChunk("IDAT", await deflate(pixels)),
    pngChunk("IEND", new Uint8Array(0)),
  ];
  const png = new Uint8Array(parts.reduce((total, part) => total + part.length, 0));
  let cursor = 0;
  for (const part of parts) {
    png.set(part, cursor);
    cursor += part.length;
  }
  return png;
}

/* ------------------------------------------------------------------ */
/* Embedded sample videos                                              */
/* ------------------------------------------------------------------ */

/**
 * Two ~1 s H.264 clips (320x240, constrained baseline profile, faststart)
 * produced with
 *   ffmpeg -f lavfi -i "color=c=0xC0457A:s=320x240:d=1:r=12" -an -c:v libx264 \
 *     -profile:v baseline -pix_fmt yuv420p -movflags +faststart clip.mp4
 * (the second uses c=0x2E7D5B) and embedded so the Worker needs no file system
 * access. They exercise the video filter, the "Video" chip and the viewer's
 * <video> element.
 */
const SAMPLE_VIDEOS: ReadonlyArray<string> = [
  "",
  "",
];

function base64ToBytes(value: string) {
  const binary = atob(value);
  return Uint8Array.from(binary, (character) => character.charCodeAt(0));
}

/* ------------------------------------------------------------------ */
/* Response helper                                                     */
/* ------------------------------------------------------------------ */

export async function sampleMediaResponse(
  objectKey: string,
  request: Request,
  options: { contentType: string; filename: string; download?: boolean; cacheControl?: string },
) {
  if (!objectKey.startsWith(SAMPLE_OBJECT_PREFIX)) return null;
  // Reserved keys are not real Drive IDs, so never fall through to Drive: the
  // object simply does not exist when the local-only gates are not met.
  if (!localSampleMediaEnabled(request)) return new Response("Not found", { status: 404 });

  const [kind, indexText] = objectKey.slice(SAMPLE_OBJECT_PREFIX.length).split(":");
  const index = Number.parseInt(indexText ?? "0", 10) || 0;
  let bytes: Uint8Array | null = null;
  if (kind === "photo") bytes = await samplePng(index);
  if (kind === "video") bytes = base64ToBytes(SAMPLE_VIDEOS[Math.abs(index) % SAMPLE_VIDEOS.length]);
  if (!bytes) return new Response("Not found", { status: 404 });

  const headers = new Headers({
    "Content-Type": options.contentType,
    "Cache-Control": options.cacheControl ?? "private, max-age=3600",
    "Accept-Ranges": "bytes",
    "Content-Disposition": `${options.download ? "attachment" : "inline"}; filename*=UTF-8''${encodeURIComponent(options.filename)}`,
  });

  // <video> elements issue range requests; honour them like the Drive proxy.
  const match = request.headers.get("range")?.match(/^bytes=(\d*)-(\d*)$/);
  if (match && (match[1] || match[2])) {
    // "bytes=-N" is a suffix range: the last N bytes, ending at bytes.length - 1.
    // "bytes=N-" / "bytes=N-M" are regular ranges starting at N.
    const suffix = !match[1];
    const start = suffix
      ? Math.max(0, bytes.length - Number.parseInt(match[2], 10))
      : Number.parseInt(match[1], 10);
    const end = suffix || !match[2] ? bytes.length - 1 : Math.min(Number.parseInt(match[2], 10), bytes.length - 1);
    if (start >= bytes.length || start > end) {
      headers.set("Content-Range", `bytes */${bytes.length}`);
      return new Response(null, { status: 416, headers });
    }
    headers.set("Content-Range", `bytes ${start}-${end}/${bytes.length}`);
    headers.set("Content-Length", String(end - start + 1));
    return new Response(bytes.slice(start, end + 1), { status: 206, headers });
  }

  headers.set("Content-Length", String(bytes.length));
  return new Response(bytes, { status: 200, headers });
}
